actor BackgroundExecutionLease {
    struct Lease: Sendable, Equatable {
        let category: String
        let reason: String
        let acquiredAt: Date
        let expiresAt: Date
    }

    private var leases: [String: Lease] = [:]

    func acquire(category: String, reason: String, ttl: TimeInterval = 300, now: Date = Date()) -> Bool {
        cleanupExpired(now: now)
        guard leases[category] == nil else { return false }
        leases[category] = Lease(category: category, reason: reason, acquiredAt: now, expiresAt: now.addingTimeInterval(ttl))
        return true
    }

    func release(category: String) {
        leases.removeValue(forKey: category)
    }

    func activeLease(category: String, now: Date = Date()) -> Lease? {
        cleanupExpired(now: now)
        return leases[category]
    }

    private func cleanupExpired(now: Date) {
        leases = leases.filter { $0.value.expiresAt > now }
    }
}","imports":["Foundation"],"language":"swift","module":"Background","path":"ios/Lumen/Background/BackgroundExecutionLease.swift","responsibility":"`ios/Lumen/Background/BackgroundExecutionLease.swift` owns BackgroundExecutionLease behavior and defines: BackgroundExecutionLease, Lease, acquire, release, activeLease, cleanupExpired, category, reason, acquiredAt, expiresAt.","sourceHash":"7cbf5b28bbe2b967c93eed945965e0ee0f9207849b40cb49b0edaa47f4dbd98e","symbols":["BackgroundExecutionLease","Lease","acquire","release","activeLease","cleanupExpired","category","reason","acquiredAt","expiresAt","leases"]}

